/**
 * FolderItem Component - Displays a single folder
 * 
 * Responsibilities:
 * - Show folder name
 * - Handle folder click (navigate into)
 * - Show folder icon
 * 
 * Import rules:
 * - Can import: hooks (if needed)
 * - Can import: other components
 * - Should NOT import: services, pages
 */

import React, { useState, useRef, useEffect } from 'react';
import { formatDate } from '../../utils/helpers';

const FolderItem = ({ 
  folder, 
  onNavigate, 
  onDelete, 
  viewMode = 'list',
  isSelected = false,
  onSelect,
  onShare,
  onCopyLink,
  onRename,
  onMove,
  onCopy,
  onManageAccess
}) => {
  const [isHovered, setIsHovered] = useState(false);
  const [showContextMenu, setShowContextMenu] = useState(false);
  const contextMenuRef = useRef(null);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (contextMenuRef.current && !contextMenuRef.current.contains(event.target)) {
        setShowContextMenu(false);
      }
    };

    if (showContextMenu) {
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }
  }, [showContextMenu]);

  const handleClick = (e) => {
    // Don't navigate if clicking on checkbox, context menu, delete button, or action buttons
    if (
      e.target.closest('.folder-checkbox') ||
      e.target.closest('.folder-context-menu') ||
      e.target.closest('.folder-actions') || 
      e.target.closest('.folder-actions-grid')
    ) {
      return;
    }
    if (onNavigate) {
      onNavigate(folder.id, folder.name);
    }
  };

  const handleCheckboxChange = (e) => {
    e.stopPropagation();
    if (onSelect) {
      onSelect(folder.id, 'folder');
    }
  };

  const handleContextMenuClick = (e) => {
    e.stopPropagation();
    setShowContextMenu(!showContextMenu);
  };

  const handleContextAction = (action, e) => {
    e.stopPropagation();
    setShowContextMenu(false);
    
    switch (action) {
      case 'share':
        if (onShare) onShare(folder.id, 'folder');
        break;
      case 'copyLink':
        if (onCopyLink) onCopyLink(folder.id, 'folder');
        break;
      case 'manageAccess':
        if (onManageAccess) onManageAccess(folder.id, 'folder');
        break;
      case 'delete':
        if (onDelete) onDelete(folder.id);
        break;
      case 'rename':
        if (onRename) onRename(folder.id, 'folder', folder.name);
        break;
      case 'move':
        if (onMove) onMove(folder.id, 'folder');
        break;
      case 'copy':
        if (onCopy) onCopy(folder.id, 'folder');
        break;
      case 'details':
        window.alert(`Folder Details:\nName: ${folder.name}\nItems: ${folder.item_count || 0}`);
        break;
      default:
        break;
    }
  };

  if (viewMode === 'grid') {
    return (
      <div 
        className="folder-item folder-item-grid"
        onClick={handleClick}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
      >
        <div className="folder-item-grid-content">
          <div className="folder-icon-grid">
            <svg width="48" height="48" viewBox="0 0 24 24" fill="none">
              <path d="M10 4H4C2.9 4 2.01 4.9 2.01 6L2 18C2 19.1 2.9 20 4 20H20C21.1 20 22 19.1 22 18V8C22 6.9 21.1 6 20 6H12L10 4Z" fill="#FFA726"/>
            </svg>
            {isHovered && (
              <div className="folder-actions-grid" onClick={(e) => e.stopPropagation()}>
                {onDelete && (
                  <button 
                    className="btn-icon-grid" 
                    onClick={() => onDelete(folder.id)}
                    title="Delete"
                  >
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                      <path d="M6 19C6 20.1 6.9 21 8 21H16C17.1 21 18 20.1 18 19V7H6V19ZM19 4H15.5L14.5 3H9.5L8.5 4H5V6H19V4Z" fill="currentColor"/>
                    </svg>
                  </button>
                )}
              </div>
            )}
          </div>
          <div className="folder-info-grid">
            <div className="folder-name-grid" title={folder.name}>{folder.name}</div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div 
      className={`folder-item ${isSelected ? 'selected' : ''}`}
      onClick={handleClick}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {viewMode === 'list' && (
        <div className={`folder-checkbox-wrapper ${isHovered || isSelected ? 'visible' : ''}`}>
          <input
            type="checkbox"
            className="folder-checkbox"
            checked={isSelected}
            onChange={handleCheckboxChange}
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}
      <div className="folder-icon">
        <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
          <path d="M10 4H4C2.9 4 2.01 4.9 2.01 6L2 18C2 19.1 2.9 20 4 20H20C21.1 20 22 19.1 22 18V8C22 6.9 21.1 6 20 6H12L10 4Z" fill="currentColor"/>
        </svg>
      </div>
      <div className="folder-name" title={folder.name}>{folder.name}</div>
      <div className="file-modified">
        {folder.updated_at || folder.created_at ? formatDate(folder.updated_at || folder.created_at) : '—'}
      </div>
      <div className="file-size">—</div>
      <div className="file-sharing">
        <span className="sharing-status">Private</span>
      </div>
      {viewMode === 'list' && (
        <div className="folder-context-menu-wrapper" ref={contextMenuRef}>
          <button 
            className="folder-context-menu-btn"
            onClick={handleContextMenuClick}
            title="More options"
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
              <path d="M12 8C13.1 8 14 7.1 14 6C14 4.9 13.1 4 12 4C10.9 4 10 4.9 10 6C10 7.1 10.9 8 12 8ZM12 10C10.9 10 10 10.9 10 12C10 13.1 10.9 14 12 14C13.1 14 14 13.1 14 12C14 10.9 13.1 10 12 10ZM12 16C10.9 16 10 16.9 10 18C10 19.1 10.9 20 12 20C13.1 20 14 19.1 14 18C14 16.9 13.1 16 12 16Z" fill="currentColor"/>
            </svg>
          </button>
          {showContextMenu && (
            <div className="folder-context-menu">
              <button className="context-menu-item" onClick={(e) => handleContextAction('share', e)}>
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                  <path d="M18 16.08C17.24 16.08 16.56 16.38 16.04 16.85L8.91 12.7C8.96 12.47 9 12.24 9 12C9 11.76 8.96 11.53 8.91 11.3L15.96 7.19C16.5 7.69 17.21 8 18 8C19.66 8 21 6.66 21 5C21 3.34 19.66 2 18 2C16.34 2 15 3.34 15 5C15 5.24 15.04 5.47 15.09 5.7L8.04 9.81C7.5 9.31 6.79 9 6 9C4.34 9 3 10.34 3 12C3 13.66 4.34 15 6 15C6.79 15 7.5 14.69 8.04 14.19L15.16 18.34C15.11 18.55 15.08 18.77 15.08 19C15.08 20.61 16.39 21.92 18 21.92C19.61 21.92 20.92 20.61 20.92 19C20.92 17.39 19.61 16.08 18 16.08Z" fill="currentColor"/>
                </svg>
                <span>Share</span>
              </button>
              <button className="context-menu-item" onClick={(e) => handleContextAction('copyLink', e)}>
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                  <path d="M3.9 12C3.9 10.29 5.29 8.9 7 8.9H11V7H7C4.24 7 2 9.24 2 12C2 14.76 4.24 17 7 17H11V15.1H7C5.29 15.1 3.9 13.71 3.9 12ZM8 13H16V11H8V13ZM17 7H13V8.9H17C18.71 8.9 20.1 10.29 20.1 12C20.1 13.71 18.71 15.1 17 15.1H13V17H17C19.76 17 22 14.76 22 12C22 9.24 19.76 7 17 7Z" fill="currentColor"/>
                </svg>
                <span>Copy link</span>
              </button>
              <button className="context-menu-item" onClick={(e) => handleContextAction('manageAccess', e)}>
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                  <path d="M16 11C17.66 11 18.99 9.66 18.99 8C18.99 6.34 17.66 5 16 5C14.34 5 13 6.34 13 8C13 9.66 14.34 11 16 11ZM8 11C9.66 11 10.99 9.66 10.99 8C10.99 6.34 9.66 5 8 5C6.34 5 5 6.34 5 8C5 9.66 6.34 11 8 11ZM8 13C5.67 13 1 14.17 1 16.5V19H15V16.5C15 14.17 10.33 13 8 13ZM16 13C15.71 13 15.38 13.02 15.03 13.05C16.19 13.89 17 15 17 16.5V19H23V16.5C23 14.17 18.33 13 16 13Z" fill="currentColor"/>
                </svg>
                <span>Manage access</span>
              </button>
              <div className="context-menu-divider"></div>
              <button className="context-menu-item" onClick={(e) => handleContextAction('delete', e)}>
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                  <path d="M6 19C6 20.1 6.9 21 8 21H16C17.1 21 18 20.1 18 19V7H6V19ZM19 4H15.5L14.5 3H9.5L8.5 4H5V6H19V4Z" fill="currentColor"/>
                </svg>
                <span>Delete</span>
              </button>
              <button className="context-menu-item" onClick={(e) => handleContextAction('rename', e)}>
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                  <path d="M3 17.25V21H6.75L17.81 9.94L14.06 6.19L3 17.25ZM20.71 7.04C21.1 6.65 21.1 6.02 20.71 5.63L18.37 3.29C17.98 2.9 17.35 2.9 16.96 3.29L15.12 5.13L18.87 8.88L20.71 7.04Z" fill="currentColor"/>
                </svg>
                <span>Rename</span>
              </button>
              <button className="context-menu-item" onClick={(e) => handleContextAction('move', e)}>
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                  <path d="M10 4H4C2.9 4 2.01 4.9 2.01 6L2 18C2 19.1 2.9 20 4 20H20C21.1 20 22 19.1 22 18V8C22 6.9 21.1 6 20 6H12L10 4Z" fill="currentColor"/>
                  <path d="M16 13L13 10V12H9V14H13V16L16 13Z" fill="currentColor"/>
                </svg>
                <span>Move to</span>
              </button>
              <button className="context-menu-item" onClick={(e) => handleContextAction('copy', e)}>
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                  <path d="M10 4H4C2.9 4 2.01 4.9 2.01 6L2 18C2 19.1 2.9 20 4 20H20C21.1 20 22 19.1 22 18V8C22 6.9 21.1 6 20 6H12L10 4Z" fill="currentColor"/>
                  <path d="M16 13L13 10V12H9V14H13V16L16 13Z" fill="currentColor"/>
                  <path d="M20 2H10C8.9 2 8 2.9 8 4V6H10V4H20V14H18V16H20C21.1 16 22 15.1 22 14V4C22 2.9 21.1 2 20 2Z" fill="currentColor"/>
                </svg>
                <span>Copy to</span>
              </button>
              <button className="context-menu-item" onClick={(e) => handleContextAction('details', e)}>
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                  <path d="M14 2H6C4.9 2 4 2.9 4 4V20C4 21.1 4.89 22 5.99 22H18C19.1 22 20 21.1 20 20V8L14 2ZM18 20H6V4H13V9H18V20Z" fill="currentColor"/>
                  <path d="M7 12H17V14H7V12ZM7 16H17V18H7V16Z" fill="currentColor"/>
                </svg>
                <span>Details</span>
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default FolderItem;
